entries[129410] = { ["name"] = "Tödliches Gift", ["text"] = "Wirken in 3 sek.\nBenötigt Einhändige Nahkampfwaffe\nÜberzieht Eure Waffen mit einem tödlichen Gift , das 1 Stunde lang an ihnen haften bleibt. Bei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften. Das Gift verursacht im Verlauf von 12 Sek. [(11.374% der Angriffskraft) * 4] Naturschaden. Weitere Anwendungen auf das Ziel während der Effektdauer verursachen sofort (8.14% der Angriffskraft) Naturschaden.\n(Procchance: 30%)" }
entries[129411] = { ["name"] = "Totem der Erdbindung", ["text"] = "30 Mana\nSofort\nTools: Erdtotem\nBeschwört ein Totem der Erdbindung, das 45 Sek. lang bestehen bleibt und in regelmäßigen Abständen die Bewegungsgeschwindigkeit von in der Nähe befindlichen Feinden auf 50% des normalen Tempos verringert." }
entries[129412] = { ["name"] = "Wundgift", ["text"] = "Wirken in 3 sek.\nBenötigt Einhändige Nahkampfwaffe\nÜberzieht Eure Waffen mit einem tödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei jedem Angriff besteht eine Chance von 30%, den Gegner zu vergiften, was sofort (4.07% der Angriffskraft) Naturschaden verursacht sowie 12 Sek. lang die erhaltenen Heileffekte verringert.\n(Procchance: 30%)" }
